-- User-created buttons without source metadata fall back to their owning page name.
UPDATE sys_menu button JOIN sys_menu page ON page.id=button.parent_id
SET button.name=CONCAT(page.name,' · ',button.name),button.version=button.version+1
WHERE button.type='BUTTON' AND button.name NOT LIKE '% · %';
UPDATE sys_permission permission JOIN sys_menu button ON button.code=permission.permission_code AND button.type='BUTTON'
SET permission.permission_name=button.name WHERE permission.client_type='WEB';
